"use client";
import { useState, type FormEvent } from "react";
import { useAction, Feedback, money } from "./workspace";

/**
 * Demo-only instant settlement. The four-digit value is generated by the API
 * and displayed once. It is never a real Orange Money PIN and is never sent to
 * a payment provider.
 */
export function InstantPayment({
  claim,
  reload,
}: {
  claim: any;
  reload: () => void;
}) {
  const action = useAction();
  const [prepared, setPrepared] = useState<any>(null);
  const [settled, setSettled] = useState<any>(null);

  if (settled) {
    const wallet = settled.wallet;
    return (
      <section className="panel">
        <h2>Instant settlement complete</h2>
        <div className="notice">
          <b>Simulated settlement.</b> No real Orange Money API is connected,
          no real PIN was used and no real funds moved.
        </div>
        <dl className="key-values">
          <div>
            <dt>Payment</dt>
            <dd className="sec-mono">{settled.payment.id.slice(0, 8)}</dd>
          </div>
          <div>
            <dt>State</dt>
            <dd>{settled.payment.state}</dd>
          </div>
          <div>
            <dt>Insurer wallet debit</dt>
            <dd>{money(wallet?.insurer_debit_minor, claim.currency)}</dd>
          </div>
          <div>
            <dt>Facility wallet credit</dt>
            <dd>{money(wallet?.facility_credit_minor, claim.currency)}</dd>
          </div>
          <div>
            <dt>LUX share</dt>
            <dd>{money(wallet?.lux_minor, claim.currency)}</dd>
          </div>
          <div>
            <dt>Orange share</dt>
            <dd>{money(wallet?.orange_minor, claim.currency)}</dd>
          </div>
        </dl>
        <p>{settled.notice}</p>
        <p>
          The facility and both fee-share wallets have already been updated.
          Open the wallet area to watch the three-second refresh.
        </p>
      </section>
    );
  }

  if (prepared) {
    const payment = prepared.payment;
    const fee = payment.fee_snapshot;
    return (
      <section className="panel">
        <h2>Confirm simulated Orange Money payment</h2>
        <div className="notice" role="note">
          <b>SIMULATION ONLY.</b> Enter the four-digit demo code shown below.
          Never enter your real Orange Money PIN in LUX HealthPay. This code was
          generated by this demo server and is not stored in readable form.
        </div>
        <p>
          Demo confirmation code:{" "}
          <strong
            className="sec-mono"
            style={{ fontSize: 28, letterSpacing: 8 }}
          >
            {prepared.demoCode}
          </strong>
        </p>
        <dl className="key-values">
          <div>
            <dt>Amount to facility</dt>
            <dd>{money(fee.base, claim.currency)}</dd>
          </div>
          <div>
            <dt>Insurer debit</dt>
            <dd>{money(fee.insurerDebit, claim.currency)}</dd>
          </div>
          <div>
            <dt>Service fee</dt>
            <dd>
              {money(fee.total, claim.currency)} · {money(fee.lux, claim.currency)}{" "}
              LUX / {money(fee.orange, claim.currency)} Orange
            </dd>
          </div>
        </dl>
        <Feedback action={action} />
        <form
          className="stack-form"
          onSubmit={async (event: FormEvent<HTMLFormElement>) => {
            event.preventDefault();
            const code = String(
              new FormData(event.currentTarget).get("demoCode") || "",
            );
            const result = await action.run(
              `/payments/${payment.id}/instant-payment`,
              { challengeId: prepared.challengeId, demoCode: code },
              payment.version,
            );
            if (result) {
              setSettled(result);
              setPrepared(null);
              reload();
            }
          }}
        >
          <label>
            Four-digit demo confirmation code
            <input
              name="demoCode"
              inputMode="numeric"
              autoComplete="one-time-code"
              pattern="[0-9]{4}"
              maxLength={4}
              required
              autoFocus
            />
          </label>
          <button className="button" disabled={action.busy}>
            Settle instantly (simulated)
          </button>
          <button
            type="button"
            className="button secondary"
            onClick={() => setPrepared(null)}
          >
            Cancel
          </button>
        </form>
      </section>
    );
  }

  return (
    <section className="panel">
      <h2>Instant Orange Money payment</h2>
      <p>
        Pay the facility immediately from the insurer's simulated Orange Money
        wallet. The facility receives the payment on its dashboard, and the LUX
        and Orange shares are recorded at the same time.
      </p>
      <dl className="key-values">
        <div>
          <dt>Approved payable</dt>
          <dd>{money(claim.approved_minor, claim.currency)}</dd>
        </div>
        <div>
          <dt>Already allocated</dt>
          <dd>{money(claim.allocatedMinor, claim.currency)}</dd>
        </div>
        <div>
          <dt>Remaining</dt>
          <dd>{money(claim.payableMinor, claim.currency)}</dd>
        </div>
      </dl>
      <div className="notice">
        This is a simulation. The next step issues a one-time four-digit demo
        code; it is not a real Orange Money PIN and no real money moves.
      </div>
      <Feedback action={action} />
      <button
        className="button"
        disabled={action.busy || BigInt(claim.payableMinor || 0) <= 0n}
        onClick={async () => {
          const result = await action.run(
            `/claims/${claim.id}/instant-payment`,
            {
              amountMinor: claim.payableMinor,
              reason:
                "Synthetic instantly settled demonstration; not a real insurance payment decision.",
            },
          );
          if (result) setPrepared(result);
        }}
      >
        Prepare instant payment
      </button>
    </section>
  );
}
